mapper.select:
SELECT
COALESCE(SUM(POINT_AMOUNT), 0) FROM user_point
WHERE USER_ID = #{userId}

mapper.update:
UPDATE user_point
SET
ORD_NO = #{ordNo}
WHERE
POINT_NO = #{pointNo}

UPDATE product
SET
STOCK_QTY = STOCK_QTY - #{QTY}
WHERE
PRODUCT_NO = #{PRODUCT_NO}
AND STOCK_QTY >= #{QTY}

mapper.delete:
DELETE FROM cart
WHERE
CART_NO = #{CART_NO}
AND USER_ID = #{userId}

mapper.update:
UPDATE payment_master
SET PAY_STATUS = 'REF'
WHERE PAY_NO = #{payNo}

UPDATE reservation
SET RSV_STATUS = 'CAN'
WHERE RSV_NO = #{rsvNo}
